    fun all(): List<PreferenceDefinition> = definitions.toList()
    fun inGroup(group: String) = definitions.filter { it.group.equals(group, true) }
    fun find(key: String) = definitions.firstOrNull { it.key.equals(key, true) }
    fun enabledByDefault() = definitions.filter { it.defaultEnabled }
    fun search(label: String) = definitions.filter { it.label.contains(label, true) }
